const { deliver } = require('/workspace/src/dispatcher.js');

(async () => {
  // 1) Retries a 502 and succeeds on 3rd attempt, sends Idempotency-Key header
  let calls = [];
  let io = {
    post: async (path, ev, opts) => {
      calls.push({ path, ev, opts });
      return calls.length < 3 ? { status: 502 } : { status: 200, ok: true };
    },
    sleep: async (ms) => { console.log('sleep', ms); },
  };
  let res = await deliver(io, { id: 'evt_1' });
  console.log('test1 calls:', calls.length, 'res:', res.status);
  console.log('test1 header:', JSON.stringify(calls[0].opts.headers));

  // 2) No retry on 4xx
  calls = [];
  io = { post: async () => { calls.push(1); return { status: 400 }; }, sleep: async () => {} };
  res = await deliver(io, { id: 'evt_2' });
  console.log('test2 calls:', calls.length, 'res:', res.status);

  // 3) Exhausts 5 attempts on persistent 502, returns last 502
  calls = [];
  io = { post: async () => { calls.push(1); return { status: 502 }; }, sleep: async () => {} };
  res = await deliver(io, { id: 'evt_3' });
  console.log('test3 calls:', calls.length, 'res:', res.status);

  // 4) No event id -> single attempt, no retry, no options
  calls = [];
  io = { post: async (p, e, o) => { calls.push(o); return { status: 502 }; }, sleep: async () => {} };
  res = await deliver(io, { nope: true });
  console.log('test4 calls:', calls.length, 'opts:', calls[0], 'res:', res.status);
})();
"

